import{_ as i,o as t,c as a,a4 as s}from"./chunks/framework.Bzo08Beo.js";const p=JSON.parse('{"title":"Reproduce the documentation","description":"","frontmatter":{},"headers":[],"relativePath":"reference/reproducibility.md","filePath":"reference/reproducibility.md","lastUpdated":null}'),r={name:"reference/reproducibility.md"};function d(n,e,o,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="Reproduce-the-documentation" tabindex="-1">Reproduce the documentation <a class="header-anchor" href="#Reproduce-the-documentation" aria-label="Permalink to &quot;Reproduce the documentation {#Reproduce-the-documentation}&quot;">​</a></h1><p>The documentation is built with Documenter, DocumenterVitepress, Literate, and CairoMakie. Tutorial code, assertions, and figures share a single source: the scripts in <code>docs/examples/</code>.</p><h2 id="Build-everything" tabindex="-1">Build everything <a class="header-anchor" href="#Build-everything" aria-label="Permalink to &quot;Build everything {#Build-everything}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/SanjeevKhare/SkewedAxisFourierAnalysis.jl.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SkewedAxisFourierAnalysis.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.develop(path=pwd()); Pkg.instantiate()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/make.jl</span></span></code></pre></div><p>The first build downloads Julia packages and VitePress dependencies. Later builds reuse local caches. The rendered website is written to <code>docs/build/1/</code>; serve that directory beneath <code>/SkewedAxisFourierAnalysis.jl/dev/</code> for a faithful deployment preview.</p><h2 id="What-runs-during-a-build" tabindex="-1">What runs during a build <a class="header-anchor" href="#What-runs-during-a-build" aria-label="Permalink to &quot;What runs during a build {#What-runs-during-a-build}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Script</th><th style="text-align:right;">Result and numerical check</th></tr></thead><tbody><tr><td style="text-align:right;"><code>docs/examples/synthetic.jl</code></td><td style="text-align:right;">Known two-mode recovery, error below 10⁻¹², threshold sweep, saved coefficients</td></tr><tr><td style="text-align:right;"><code>docs/examples/digitization.jl</code></td><td style="text-align:right;">Synthetic RGB calibration with RMSE below 0.01; repository image conversion checked for finite values</td></tr><tr><td style="text-align:right;"><code>docs/examples/reconstruction.jl</code></td><td style="text-align:right;">Inverse-coordinate checks at 60°, 90°, and 120°, maximum error below 10⁻¹²</td></tr></tbody></table><p>These are numerical checks of the examples. The image conversion check does not validate the original material&#39;s scale or the quality of a harmonic fit to experimental data.</p><h2 id="Source-and-generated-files" tabindex="-1">Source and generated files <a class="header-anchor" href="#Source-and-generated-files" aria-label="Permalink to &quot;Source and generated files {#Source-and-generated-files}&quot;">​</a></h2><p>Edit tutorial prose and code in <code>docs/examples/*.jl</code>. Literate creates the corresponding tutorial pages; do not edit generated Markdown. Figures are regenerated in <code>docs/src/assets/figures/</code>; downloadable scripts and coefficients are staged in <code>docs/src/public/downloads/</code>.</p><p>The coordinate diagram is maintained in <code>docs/src/assets/coordinates.svg</code>; the hero in <code>docs/src/public/</code> is generated by <code>docs/illustrations.jl</code>. Theme and navigation live in <code>docs/src/.vitepress/</code>. General guide pages are ordinary Markdown under <code>docs/src/guide/</code>.</p><h2 id="Publication" tabindex="-1">Publication <a class="header-anchor" href="#Publication" aria-label="Permalink to &quot;Publication {#Publication}&quot;">​</a></h2><p>The existing GitHub Pages site serves the main-branch docs under <code>/dev/</code>. CI builds the complete documentation, runs its example assertions, and publishes on main through DocumenterVitepress. Pull requests build without publishing. Local builds publish only if <code>DOCS_DEPLOY=true</code> is deliberately set and valid deployment credentials are available.</p><p>The root address continues to redirect to <code>/dev/</code>. Legacy tutorial and API directory URLs redirect to their corresponding new pages.</p>`,14)])])}const g=i(r,[["render",d]]);export{p as __pageData,g as default};
